function parseCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i],next=text[i+1];if(char==='"'&&quoted&&next==='"'){cell+='"';i++;continue}if(char==='"'){quoted=!quoted;continue}if(char===','&&!quoted){row.push(cell.trim());cell='';continue}if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&next==='\n')i++;row.push(cell.trim());cell='';if(row.some(value=>value!==''))rows.push(row);row=[];continue}cell+=char}if(cell!==''||row.length){row.push(cell.trim());if(row.some(value=>value!==''))rows.push(row)}if(!rows.length)return[];const headers=rows.shift().map(value=>value.toLowerCase().trim());return rows.map(values=>Object.fromEntries(headers.map((header,index)=>[header,values[index]??''])))}
const csvValue=(row,key)=>String(row[key]??'').trim();
function csvBool(value){return !['false','0','no','n','inactive','hidden'].includes(String(value).toLowerCase())}
function resolveCsvCategory(row){if(csvValue(row,'category_id'))return state.categories.find(category=>String(category.id)===csvValue(row,'category_id'));const wanted=csvValue(row,'category_name').toLowerCase();return state.categories.find(category=>String(category.name).toLowerCase()===wanted)}
function resolveCsvSubcategory(row,category){if(csvValue(row,'subcategory_id'))return state.subcategories.find(subcategory=>String(subcategory.id)===csvValue(row,'subcategory_id'));const wanted=csvValue(row,'subcategory_name').toLowerCase();return state.subcategories.find(subcategory=>String(subcategory.name).toLowerCase()===wanted&&(!category||String(subcategory.category_id)===String(category.id)))}
function csvProductPayload(row){const name=csvValue(row,'name'),price=Number(csvValue(row,'price')),mrpValue=csvValue(row,'mrp'),mrp=mrpValue===''?null:Number(mrpValue),category=resolveCsvCategory(row),subcategory=resolveCsvSubcategory(row,category);if(!name)throw new Error('name is required');if(!Number.isFinite(price)||price<0)throw new Error('price must be a non-negative number');if(mrp!==null&&(!Number.isFinite(mrp)||mrp<0))throw new Error('mrp must be a non-negative number');if(!category)throw new Error('category could not be matched');if(!subcategory)throw new Error('subcategory could not be matched for this category');const discount=mrp!==null&&mrp>price?Number((((mrp-price)/mrp)*100).toFixed(2)):0;const stock=csvValue(row,'stock_quantity');return{name,price,mrp,unit:csvValue(row,'unit')||null,discount_percentage:discount,delivery_eta:csvValue(row,'delivery_eta')||null,description:csvValue(row,'description')||null,image_url:csvValue(row,'image_url')||null,subcategory_id:Number(subcategory.id),category_id:category.id,is_active:csvBool(csvValue(row,'is_active')||csvValue(row,'active')),stock_quantity:stock===''?null:Number(stock)}}
